// Parse Explain Search Parameters
// Extracts query and parameters for search with scoring explanations

const inputData = $input.all();
const outputs = [];

for (const item of inputData) {
  const input = item.json;

  // Build the search payload
  const searchPayload = {
    query: input.query || "",
    limit: input.limit !== undefined ? parseInt(input.limit) : 5,
    explain_scores: true, // Always true for this endpoint
    min_score: input.min_score !== undefined ? parseFloat(input.min_score) : 0.6,
    min_quality: input.min_quality !== undefined ? parseFloat(input.min_quality) : 0.65
  };

  // Validate query is not empty
  if (!searchPayload.query || searchPayload.query.trim() === "") {
    throw new Error("Query parameter is required and cannot be empty for explained search");
  }

  // Validate limit (keep it small for explained search)
  if (searchPayload.limit < 1 || searchPayload.limit > 20) {
    throw new Error("Limit must be between 1 and 20 for explained search (detailed analysis)");
  }

  outputs.push({ json: searchPayload });
}

return outputs;

// Format Explained Search Results
// Formats results with detailed scoring explanations and relevance factors

const inputData = $input.all();
const outputs = [];

for (const item of inputData) {
  const response = item.json;

  // Check if we have results
  if (!response.results || response.results.length === 0) {
    outputs.push({
      json: {
        success: true,
        message: "No results found to explain. Try: (1) broader search terms, (2) lower min_score threshold.",
        query: response.query || "",
        results_count: 0,
        results_with_explanations: []
      }
    });
    continue;
  }

  // Format results with detailed explanations
  const formattedResults = response.results.map((result, index) => {
    // Calculate score components
    const vectorScore = result.score || 0;
    const qualityScore = result.quality_score || 0;
    const finalScore = (vectorScore + qualityScore) / 2;

    // Determine relevance factors
    const relevanceFactors = analyzeRelevance(result, response.query);

    return {
      rank: index + 1,
      document_code: result.document_id || "Unknown",
      title: result.document_name || "Untitled Document",
      department: result.department || "Unknown",
      document_type: result.document_type_category || "Unknown",
      version: result.version || "N/A",

      // Scoring details
      scoring: {
        final_score: finalScore.toFixed(3),
        vector_similarity: vectorScore.toFixed(3),
        quality_score: qualityScore.toFixed(3),
        passed_min_score: vectorScore >= (response.min_score || 0.6),
        passed_quality: qualityScore >= (response.min_quality || 0.95)
      },

      // Relevance explanation
      relevance_explanation: {
        factors: relevanceFactors,
        summary: generateRelevanceSummary(relevanceFactors, vectorScore)
      },

      // Why this result ranked here
      ranking_explanation: generateRankingExplanation(index + 1, vectorScore, qualityScore, relevanceFactors),

      content_snippet: result.content ? result.content.substring(0, 300) + "..." : "",
      sharepoint_url: result.document_url || null,

      // Generate citation format
      citation: `**${result.document_id || "Unknown"}** (${
        result.document_name || "Untitled"
      }${result.version ? ", " + result.version : ""})`
    };
  });

  // Calculate query analysis
  const queryAnalysis = analyzeQuery(response.query, formattedResults);

  // Create formatted response
  const formattedResponse = {
    success: true,
    search_type: "explained",
    query: response.query || "",
    results_count: formattedResults.length,

    // Query analysis
    query_analysis: queryAnalysis,

    // Results with full explanations
    results_with_explanations: formattedResults,

    // Overall scoring statistics
    scoring_statistics: {
      highest_score: Math.max(...formattedResults.map(r => parseFloat(r.scoring.final_score))).toFixed(3),
      lowest_score: Math.min(...formattedResults.map(r => parseFloat(r.scoring.final_score))).toFixed(3),
      average_score: (formattedResults.reduce((sum, r) => sum + parseFloat(r.scoring.final_score), 0) / formattedResults.length).toFixed(3),
      score_range: (Math.max(...formattedResults.map(r => parseFloat(r.scoring.final_score))) - Math.min(...formattedResults.map(r => parseFloat(r.scoring.final_score)))).toFixed(3)
    },

    // Generate summary
    summary: generateExplainedSummary(formattedResults, queryAnalysis, response.query),

    // Metadata
    metadata: {
      search_time_ms: response.search_time_ms || null,
      total_documents_searched: response.total_points || null,
      min_score_threshold: response.min_score || 0.6,
      min_quality_threshold: response.min_quality || 0.95
    }
  };

  outputs.push({ json: formattedResponse });
}

// Helper function to analyze relevance factors
function analyzeRelevance(result, query) {
  const factors = [];
  const queryLower = query.toLowerCase();
  const contentLower = (result.content || "").toLowerCase();
  const titleLower = (result.document_name || "").toLowerCase();

  // Check for exact phrase match
  if (contentLower.includes(queryLower)) {
    factors.push({ factor: "Exact phrase match in content", impact: "high" });
  }

  // Check for title match
  const queryWords = queryLower.split(/\s+/);
  const titleMatches = queryWords.filter(word => titleLower.includes(word)).length;
  if (titleMatches > 0) {
    factors.push({ 
      factor: `${titleMatches}/${queryWords.length} query words in title`, 
      impact: titleMatches === queryWords.length ? "high" : "medium" 
    });
  }

  // Check for department relevance
  if (result.department && queryLower.includes(result.department.toLowerCase())) {
    factors.push({ factor: "Department mentioned in query", impact: "medium" });
  }

  // Check document type relevance
  if (result.document_type_category) {
    const typeKeywords = {
      'process': ['procedure', 'process', 'steps', 'how to'],
      'policy': ['policy', 'rule', 'regulation'],
      'manual': ['manual', 'guide', 'handbook'],
      'form_template': ['form', 'template', 'checklist']
    };

    const relevantKeywords = typeKeywords[result.document_type_category] || [];
    const matchedKeywords = relevantKeywords.filter(kw => queryLower.includes(kw));
    if (matchedKeywords.length > 0) {
      factors.push({ factor: `Document type (${result.document_type_category}) matches query intent`, impact: "medium" });
    }
  }

  // Check for recent document
  if (result.updated_date) {
    const updateDate = new Date(result.updated_date);
    const sixMonthsAgo = new Date();
    sixMonthsAgo.setMonth(sixMonthsAgo.getMonth() - 6);
    if (updateDate > sixMonthsAgo) {
      factors.push({ factor: "Recently updated document (< 6 months)", impact: "low" });
    }
  }

  return factors.length > 0 ? factors : [{ factor: "Semantic similarity (vector embeddings)", impact: "high" }];
}

// Helper function to generate relevance summary
function generateRelevanceSummary(factors, score) {
  const highImpact = factors.filter(f => f.impact === "high").length;
  const mediumImpact = factors.filter(f => f.impact === "medium").length;

  if (score > 0.9) {
    return `Excellent match (${highImpact} high-impact factors)`;
  } else if (score > 0.8) {
    return `Strong match (${highImpact + mediumImpact} relevant factors)`;
  } else if (score > 0.7) {
    return `Good match (${factors.length} relevance factors)`;
  } else {
    return `Moderate match (primarily semantic similarity)`;
  }
}

// Helper function to generate ranking explanation
function generateRankingExplanation(rank, vectorScore, qualityScore, factors) {
  let explanation = `Ranked #${rank} because: `;

  if (rank === 1) {
    explanation += "Highest combined score (vector similarity + quality). ";
  } else {
    explanation += `${rank === 2 ? "Second" : rank === 3 ? "Third" : rank + "th"} highest combined score. `;
  }

  if (vectorScore > 0.9) {
    explanation += "Exceptional semantic match. ";
  } else if (vectorScore > 0.8) {
    explanation += "Strong semantic relevance. ";
  }

  const highFactors = factors.filter(f => f.impact === "high");
  if (highFactors.length > 0) {
    explanation += `High-impact factors: ${highFactors.map(f => f.factor).join(", ")}.`;
  }

  return explanation;
}

// Helper function to analyze query
function analyzeQuery(query, results) {
  const words = query.toLowerCase().split(/\s+/).filter(w => w.length > 2);

  return {
    query_length: query.length,
    word_count: words.length,
    query_type: words.length === 1 ? "single-term" : words.length < 4 ? "short" : "detailed",
    suggested_optimization: words.length === 1 ? "Consider adding more context for better results" : 
                           words.length > 10 ? "Query is detailed - results should be highly specific" :
                           "Query length is optimal",
    results_quality: results.length > 0 ? 
      (parseFloat(results[0].scoring.final_score) > 0.9 ? "Excellent" :
       parseFloat(results[0].scoring.final_score) > 0.8 ? "Good" :
       parseFloat(results[0].scoring.final_score) > 0.7 ? "Fair" : "Low") : "N/A"
  };
}

// Helper function to generate summary
function generateExplainedSummary(results, queryAnalysis, query) {
  if (results.length === 0) {
    return `No results found for "${query}".`;
  }

  const topResult = results[0];
  let summary = `Search Explanation for "${query}"\n\n`;
  summary += `Query Analysis: ${queryAnalysis.query_type} query, ${queryAnalysis.results_quality} results quality\n\n`;
  summary += `Top result: ${topResult.citation}\n`;
  summary += `Score: ${topResult.scoring.final_score} (vector: ${topResult.scoring.vector_similarity}, quality: ${topResult.scoring.quality_score})\n`;
  summary += `Relevance: ${topResult.relevance_explanation.summary}\n\n`;
  summary += `Key factors:\n`;
  topResult.relevance_explanation.factors.slice(0, 3).forEach((f, i) => {
    summary += `${i + 1}. ${f.factor} (${f.impact} impact)\n`;
  });

  return summary;
}

return outputs;
